const ELEMENT_PROP_KEYS = new Set(["theme","claim","rest","dropAt","pullLen","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  claim: "Stop making\nlaunch videos",
  rest: "by hand.",
  dropAt: 40,
  pullLen: 40,
  fontFamily: "Outfit",
  scale: 1,
  delay: 0,
  speed: 1,
};

type OutOfContextElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof OutOfContextBase>;

const OutOfContextInner = forwardRef<
  HTMLDivElement,
  OutOfContextElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<OutOfContext>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <OutOfContextBase
          {...(componentProps as unknown as ComponentProps<typeof OutOfContextBase>)}
        />
      </div>
    </Sequence>
  );
});

export const OutOfContext = Interactive.withSchema({
